// Fixed global definitions
#define BITSET_BYTES  1024
// % target bit-saturation threshold
#define TARGET_DENSITY  25 // gives 25-43% (?)

// TODO: assert char is unsigned

// default target platform
//typedef uint16_t uint;

// Global RAM scratchpad area
char bitset[BITSET_BYTES];

/*
 * 1. LIGHTWEIGHT 13-BIT HYBRID HASH FUNCTION
 * Generates an index from 0 to 8191.
 * Uses a rolling shift-and-add mix that compiles beautifully down
 * to raw A, X, Y register operations on a 6502.
 */
uint hash_trigram(char* s) {
  uint h = 0;
  char a= s[0], b= s[1], c= s[2];
    
  // reject non \w, and single char
  if (!isalnum(a) || !isalnum(b) || ((a|b|c)&0x80)) return 0;
  if (!isalnum(c)) c= 0;

  // Process exactly 3 characters (or stop early if null-terminator hit)
  h = (tolower(a) << 4) ^ tolower(b);
  if (c) { h = (h << 4) ^ tolower(c); }
    
  return h & 0x1FFF; // Restrict output cleanly to 13 bits (0 to 8191)
}

uint hash_unigram(char* s, unsigned char len) {
  uint h = 5381;
  while (len--) {
    h = ((h << 3) + h) ^ tolower(*s++);
  }
  return h & 0x1FFF;
}

uint hash_bigram(uint hash1, uint hash2) {
  // Directional merge: Rotate left 3 bits, then XOR
  uint h = (hash1 << 3) | (hash1 >> 10);
  return (h ^ hash2) & 0x1FFF;
}

// Indexer
//
// Streams through a null-terminated string.
//
// Extracts:
// - trigrams
// - single-word unigrams
// - directional bigrams
//
// setting positional bits in bitset
 
void index_string(char* text) {
  char *p = text, *wstart = text;
  char wlen = 0;
  uint whash = 0, last_whash = 0;
  uint i;
    
  // Step A: Clear the 1 KB bitset completely
  memset(bitset, 0, BITSET_BYTES);
    
  do {
    // tokenize word tracking spaces/punctuation boundaries
    if (isalnum(*p)) { 
      // char (TODO: stop non a-z?)
      if (!wlen) wstart = p;
      wlen++;
    } else {
      // \b - word boundary (space, control char, etc.)
      if (wlen > 0) {
	whash = hash_unigram(wstart, wlen);
                
	// Set Unigram Anchor Bit
	bitset[whash >> 3] |= (1 << (whash & 7));
                
	// if have previous word hash sequence!
	if (last_whash) {
	  i = hash_bigram(last_whash, whash);
	  bitset[i >> 3] |= (1 << (i & 7));
	}
                
	last_whash = whash;
	wlen = 0;
      }
    }

    // we do test in middle to fold trailing words
    if (!*p) break;
    
    // trigram over sliding window
    i = hash_trigram(p);
    // TODO: lookup table for 6502
    if (i) bitset[i >> 3] |= (1 << (i & 7));

    ++p;
  } while (1);
}

// popcount: Counts the '1' in bitset.
// fast, hardware-friendly popcount loop.
uint index_popcount(uint bytes) {
  uint n = 0;
  uint i;
  char b;
    
  for (i = 0; i < bytes; i++) {
    b = bitset[i];
    // Optimized 8-bit lookup-less bit enumeration
    while (b) {
      n += (b & 1);
      b >>= 1;
    }
  }
  return n;
}

// folds bitset upper OR lower till default density,
// or stops at 32 bytes.
uint fold_density, fold_size;
char fold_count;

uint fold_index(void) {
  uint z = BITSET_BYTES;
  uint bits, i, half;

  fold_count = 0;
  
  while (1) {
    bits = index_popcount(z);
    fold_density = (uint)(((unsigned long)bits * 100) / (z * 8));
        
    fprintf(stderr, "  fold #%d %d ones %d%% density %d bytes\n",
	    fold_count, bits, fold_density, z);

    // done?
    if (fold_density >= TARGET_DENSITY) break;

    if (z <= 64) break;
    
    // FOLD upper half into lower by ORing
    z>>= 1;
    for (i = 0; i < z; i++) bitset[i] |= bitset[i + z];
    ++fold_count;
  }
    
  fold_size= z;
  return fold_count;
}


// append index to a (append or created file) basename.idx
// returns: (start_offset<<8) | fold_count
// append index to a (old or created file) basename.idx
// returns: (start_offset<<8) | fold_count
unsigned long append_index(char* basename) {
  FILE* f;
  char fn[64];
  long pos = 0;

  strcpy(fn, basename);
  strcat(fn, ".idx");

  if (!(f = fopen(fn, "a+b"))) return -1;
  fseek(f, 0, SEEK_END);
  pos = ftell(f);

  // write out the folded bitset payload
  if (fwrite(bitset, 1, fold_size, f) != fold_size) {
    // TODO: on smaller platforms may write piece meal?
    fclose(f);
    return -1;
  }

  fclose(f);

  return (pos << 8) | (fold_count & 0xFF);
}



#ifndef MAIN

#define MAX (16*1024)

int main(int argc, char* argv[]) {
    FILE* f;
    char* buf= malloc(MAX);
    uint bytes, status, z, i;
    char folds;
    unsigned long posfolds;

    if (argc < 2) {
      printf("%%Error: Missing argument\n");
      printf("Usage: indexer <filename>\n");
      return 1;
    }

    if (!(f= fopen(argv[1], "rb"))) {
        printf("%%Error: Could not open file: %s\n", argv[1]);
        return 1;
    }

    bytes = fread(buf, 1, MAX-1, f);
    fclose(f);

    if (!bytes) {
        printf("%%File is empty or could not be read\n");
        return 1;
    }

    // null terminate
    buf[bytes] = 0;
    
    printf("Read %u bytes from disk.\n", bytes);
    printf("Generating virtual index...\n");

    index_string(buf);
    folds = fold_index();

    // Print diagnostic system properties and the output bitstream
    printf("\n--- INDEX COMPLETED ---\n");
    printf("Rounds Folded:  %u\n", folds);
    printf("Final Data Size: %u bytes\n", fold_size);
    printf("Storage Ratio:  %u%%\n", (uint)(((unsigned long)fold_size*100) / bytes));
    
    printf("\nIndex Preview (Hex):\n");
    for(i = 0; i < z; ++i) {
        printf("%02X ", bitset[i]);
        // Format layout cleanly into 16-byte grid rows
        if ((i & 15) == 15) putchar('\n');
    }
    putchar('\n');


    posfolds= append_index(argv[1]);

    printf("\nWrote index file %s.idx posfolds: %08x\n", argv[1], posfolds);

    free(buf);
    
    return 0;
}
#endif
